using A = BoatsNBeasts.Core.LandingAction;
using D = BoatsNBeasts.Core.SeaDuty;
using J = BoatsNBeasts.Core.SeaJob;
using S = BoatsNBeasts.Core.YardSite;

namespace BoatsNBeasts.Core;

public static partial class FarLedger
{
    static CampaignArc Pitchwake() => CampaignArc.Create("Pitchwake Strait","The Fleet That Would Stay",
        "Toma Pike’s anchor crews can arrest a walking island without spilling soup. She learned the trick on the night her city sank. Faced with migrating islands and collapsing homes, Toma is offering every town in the strait a free chain.",
        "A repaired shackle stamped with a seated woman’s shoe",
        new("Toma Pike  /  anchor captain",
            "What can a promise hold?",
            "Toma has one working anchor cradle. A hospital island has asked her to use it for one night while its ward moves aboard. A convoy of tenants wants to borrow the cradle and move its whole terrace at once. Both plans will work. Nobody has asked the island how long it can wait.",
            "Hold the infirmary",
            "Move the terrace",
            "Toma stakes out a short chain that falls free when the last ward bed leaves. She asks Latt to paint the release mark where the patients can see it.",
            "The tenants sign for the cradle together. Toma keeps her crews on the terrace until the last resident has chosen whether to go."),
        15,
        [
            Crossing("wake-pitch-entry",D.Blockade,"Free Chain",
                "Toma’s fleet has stopped a drifting schoolyard a boat length from the rocks. Her chain wall blocks the only passage into the strait. She offers a pilot and a pair of shears in the same hand.","Open a crossing through the loaded lines without fouling the schoolyard.",
                "The Port Shear","Toma’s pilot brings the children hot milk. Vara gives the shears back with the blades freshly oiled. Both crews know how to accept help.",9,J.Cut,J.Guide,J.Relay),
            Landfall("wake-drowned-stair","The Thirty-Seventh Step",
                "Toma’s old city had thirty-six steps to the landing. She says there were thirty-seven because the last was the shoe she wedged under her mother’s chair as the floor went. The step has surfaced on a passing reef.","Staircase Hart","The shoe still holds the chair level. Toma sits in it a while before asking her bosun to lift both aboard.",9,
                At(A.Brace,S.West,"City stair","Brace the surfacing step against the moving reef"),
                At(A.Haul,S.Crane,"Chair and shoe","Lift the old chair on its original supports"),
                At(A.Seat,S.East,"Thirty-seventh step","Set the shoe beneath the chair on Toma’s deck")),
            Crossing("wake-hold-night",D.Convoy,"One Night’s Hold",
                "Ward nurse Iva agrees to the anchor if she can cut it the moment her last patient chooses a bed. Toma brings the release lever into the ward herself.","Protect the infirmary movers and wait for the ward’s own release signal.",
                "Shortchain Monitor","Iva makes the cut. Two patients choose to stay with the walking island. Toma gives them the longest drinking hose on her ship.",9,J.Tow,J.Relieve,J.Guide,J.Relay),
            Landfall("wake-pitch-rivet","The Rivet Room",
                "The anchor fleet’s load tables were made in the lost city. They treat every island as a block of stone. Toma takes the crew into the rivet room to show where her mother wrote down the first exception.","The Rivet Hound","The exception reads she lifted me. An island rising under the house saved Toma’s mother for three days. Toma had remembered only the third.",9,
                At(A.Turn,S.West,"Load drum","Roll the old load drum to the storm date"),
                At(A.Haul,S.Crane,"Exception plate","Lift the lead plate under the written figures"),
                At(A.Seat,S.East,"Mother’s note","Set the scratched note beside Toma’s working chart")),
            Crossing("wake-pitch-letter",D.Salvage,"Where to Hang the Bell",
                "The drowned city’s dinner bell lies under a broken district shackle. The old households have spent years arguing over who ought to keep it. Toma has asked them to write an answer together.","Raise the split shackle and dinner bell for the gathering of households.",
                "Belfry Sawfish","No one wants the bell to stand still. Toma has the shackle straightened into a mast band and places it in her mother’s empty chair.",9,J.Track,J.Cut,J.Salvage,J.Unload),
            Crossing("wake-pitch-release",D.Convoy,"Captain Pike’s Last Anchor",
                "Toma can hold one more town back or turn her remaining chains into floating bridges. She has counted which households want to go and which ones want to stay. The arithmetic gives her enough chain for both.","Pilot Toma’s moving bridges through the last anchor fleet.",
                "The Standing Order","Toma hangs the dinner bell from the fleet’s signal mast. On its first evening round three migrating towns stop close enough to eat from one another’s pots.",9,J.Tow,J.Guide,J.Cut,J.Relay)
        ],
        Crossing("wake-pitch-terrace",D.Salvage,"Borrowed Cradle",
                "Toma’s anchor cradle went down under a falling tenement. The tenants who survived know precisely which beam to lift, though their own door is still nailed to it.","Raise the town cradle and deliver it under the tenants’ terrace.",
                "The House Weight","A short man walks through his recovered door and onto the moving terrace. Then he goes back through it to hold it for his taller wife.",9,J.Sound,J.Salvage,J.Unload));

    static IslandStory[] PitchwakeIsles() => [
        Isle("Pitchwake Strait",15,"Rosin Stack","Dedel Vane, rope dresser",
            "Dedel can name a ship by the smell of its anchor tar. A line has washed up smelling of a garden he has not visited since the old city drowned.",
            "A twist of rope that smells faintly of marigolds",
            new PostLetter("A marigold seed stuck in a coil of pitch",
                "Was there a garden on the anchor ship that visited our roof last winter?",
                "Yes. It belongs to the ship’s night watch. Please send any seeds that smell like the old south wall."),
            Crossing("wake-rosin-scent",D.Hunt,"Tar and Marigolds",
                "The line smells strongest at low tide. Dedel knows city gardens well enough to distinguish a garden wall from a municipal flowerpot.","Track the tarred line back to its fragrant source.",
                "Marigold Kite","The line runs around a houseboat’s kitchen garden. The boat has been carrying a square of old city turf for twenty years.",8,J.Track,J.Bait,J.DriveOff),
            Landfall("wake-rosin-bed","The Last Square Yard",
                "The houseboat’s last sound floorboard has fallen under the garden. Its owner wants the turf lifted without turning any of her garden creatures upside down.","Sod Oyster","A snail completes its crossing from one dandelion to the next without noticing that it has changed boats.",8,
                At(A.Brace,S.West,"Turf frame","Brace the four corners under the old turf"),
                At(A.Cut,S.East,"Floor lashings","Cut away the rotten floor lashings"),
                At(A.Haul,S.Crane,"Square yard","Lift the entire garden level")),
            Crossing("wake-rosin-lighter",D.Convoy,"The Horticultural Navy",
                "Dedel has persuaded three anchor crews to take a corner of turf each. The difference between a garden and a fleet, he says, is mostly in the watering.","Guide the garden boats through the anchor tugs.",
                "Hoehead Ray","The fourth corner goes to a tug whose cook has long maintained that the strait needs fresh chives.",8,J.Tow,J.Guide,J.Relay),
            Landfall("wake-rosin-patch","The South Wall",
                "The old kitchen wall carried a wild marigold that flowered in salt air. Dedel still has one seed. The new garden needs something the same height as the lost wall.","Trowel Gull","Dedel plants the seed against Toma’s rolled-up storm sail. When the sail opens in spring, a dozen seeds go looking for gardens of their own.",8,
                At(A.Turn,S.West,"Sunward rack","Turn the garden rack toward the afternoon light"),
                At(A.Brace,S.East,"Storm sail","Brace the furled storm sail beside the turf"),
                At(A.Seat,S.Stairs,"Marigold seed","Plant the last seed against the tall canvas"))),
        Isle("Pitchwake Strait",15,"Breakwater Sunday","Agra Palm, harbor referee",
            "Every Sunday the anchor crews row a race along the old breakwater. Agra is the only referee who remembers where it used to end. She has stopped calling winners.",
            "A referee’s flag made from two different tablecloths",
            new PostLetter("Half of a faded finish ribbon",
                "Will you call a finish if one half of each crew is still living in another port?",
                "Join the two ribbons across the water. We can call it when both boats reach home."),
            Crossing("wake-sunday-line",D.Sounding,"The Race With No Finish",
                "Agra knows the finish by the smell of Sunday dinner in the last house. No kitchen stands there now.","Sound the drowned breakwater to find the old finish line.",
                "Breadfin","The lead catches a second ribbon two house lengths farther out. The children of the old city had been running a race of their own.",8,J.Sound,J.Track,J.Relay),
            Landfall("wake-sunday-ribbon","Two Finish Lines",
                "Agra was a champion of the grown-up course. Her younger brother won the short children’s course every year because he was its sole official entrant. Neither kept the ribbon.","Bunting Crab","Agra puts the two ribbons side by side. The childish one is longer, because her brother had won so many times.",8,
                At(A.Brace,S.West,"Far ribbon post","Brace the post beside the second ribbon"),
                At(A.Cut,S.East,"Barnacled knot","Free the ribbon from the barnacled knot"),
                At(A.Seat,S.Stairs,"Two finish flags","Pin both ribbons to the referee’s board")),
            Crossing("wake-sunday-boats",D.Convoy,"A Boat From Each Half",
                "Half the former street now works on tugs; half lives in traveling towns. Agra proposes a relay where each boat hands over a saucepan rather than a baton.","Carry the two crews and their saucepan round the new Sunday course.",
                "Ladle Petrel","Both crews slow at the turn to put potatoes in the saucepan. The result is the first race to improve substantially in the middle.",8,J.Tow,J.Relieve,J.Guide),
            Landfall("wake-sunday-call","The Result Stands",
                "The two boats reach opposite sides of an empty pier at the same moment. Agra’s brother has finally come to see a grown-up race.","Line Judge Limpet","The referee calls dinner. Her brother records it in the official result book and leaves room for second helpings.",8,
                At(A.Turn,S.West,"Finish boom","Turn the boom to meet both returning boats"),
                At(A.Haul,S.Crane,"Race saucepan","Lift the saucepan onto the center of the pier"),
                At(A.Guide,S.Ferry,"Second referee","Escort Agra’s brother to the table"))),
        Isle("Pitchwake Strait",15,"Blacklead Yard","Ivvy Stoop, salvage pencil maker",
            "The salvage divers use Ivvy’s pencils because they will write underwater. The old city’s final evacuation roster turned up entirely blank. Ivvy made the pencil used to fill it.",
            "A double-ended pencil with a soft and a hard point",
            new PostLetter("A blank scrap of the evacuation list",
                "Did the pencil fail, or did our old neighbors have time to erase themselves before they left?",
                "Rub a soft pencil across the back. They wrote addresses on the page above; each family kept its own half."),
            Landfall("wake-lead-first","Page Under a Page",
                "Ivvy can feel shallow lines in the roster with the nail of her little finger. The keeper insists on using a hard pencil to reveal them.","Slate Roach","A rubbing shows lines running off both edges. The roster was a pad underneath the page everybody took away.",8,
                At(A.Brace,S.West,"Writing slate","Brace the slate under the wet roster"),
                At(A.Seat,S.East,"Soft graphite","Seat the soft graphite under the rubbing cloth"),
                At(A.Turn,S.Stairs,"Rubbing roller","Turn the roller lightly over the roster")),
            Crossing("wake-lead-page",D.Salvage,"The Address That Stayed",
                "An address runs along the edge of the rubbing and vanishes under an old iron staple. The caretaker saved a second pad beneath the lift shaft.","Raise the caretaker’s old address pad.",
                "Stapleback","The two impressions join to say find us under the yellow awning. There are nine yellow awnings in the strait.",8,J.Track,J.Salvage,J.Unload),
            Crossing("wake-lead-yellow",D.Hunt,"Nine Yellow Awnings",
                "Ivvy’s father mended awnings for a living. His stitching gives a little sideways kick on the inside corners. Vara offers to sail her past all nine.","Track the awning with Ivvy’s family stitch.",
                "Buttonbill","Under the last awning Ivvy’s two old neighbors have been waiting for the rest of the street to find them. They have kept a spare pencil sharp.",8,J.Track,J.Sound,J.DriveOff),
            Landfall("wake-lead-book","Tear Along the Fold",
                "The neighbors want to send the old addresses on without losing their only copy. Ivvy has made a pencil with two leads for just such an occasion.","Carbon Toad","Nine letters go out in envelopes with nine matching folds. The old roster goes into the stove, where it warms the hands that filled it.",8,
                At(A.Seat,S.West,"Copy pad","Seat the soft copy pad beneath the address sheets"),
                At(A.Turn,S.East,"Twin nibs","Turn the twin pencil points into line"),
                At(A.Guide,S.Ferry,"Letter carriers","Bring the carriers to their matching envelopes"))),
        Isle("Pitchwake Strait",15,"Lowered Mast","Mav Lune, dinner bell ringer",
            "Mav rang the dinner bell on the night the old city sank. He heard a second bell answer from underneath the harbor. He would like the other ringer to know the meal stayed warm.",
            "A little bell clapper cast from a soup spoon",
            new PostLetter("A spoon polished on one side only",
                "Did anybody hear our second dinner bell under the quay? We have wondered every night since.",
                "Mav heard you. At sunset he will be standing on the east side of the traveling mast with a hot bowl."),
            Landfall("wake-mast-hinge","Face the Water",
                "The old bell tower lies on its side. Mav wants to lower the mast on Toma’s tender to exactly the same angle so he can remember which way he faced.","Hinge Crow","When the mast levels out, Mav remembers turning toward the public baths. He had never looked there because the bathhouse bell was made of wood.",8,
                At(A.Brace,S.West,"Tender mast","Brace the tender mast before easing it down"),
                At(A.Turn,S.East,"Hinge pins","Turn the pins to the old tower angle"),
                At(A.Guide,S.Stairs,"Dinner ringer","Escort Mav along the lowered spar")),
            Crossing("wake-mast-bath",D.Sounding,"A Wooden Bell",
                "The public baths floated free in the sinking and have never come back to the same place twice. Mav thinks a wooden bell would sound like a spoon on a washboard.","Take bearings on the traveling bathhouse echo.",
                "Clapper Carp","A timber tub rolls in the wake, ringing on a chain of carved handles. Each handle is a door knocker from one lost home.",8,J.Track,J.Sound,J.Relay),
            Crossing("wake-mast-knock",D.Convoy,"One Knocker Per House",
                "The bathhouse keeper spent the night of the sinking collecting people through the windows. They rang the handles against the tub until Mav’s bell answered.","Guide the bathhouse and its old handles to the traveling dinner mast.",
                "Tubjaw","The keeper has been worrying for years that the ringer mistook the noise for someone asking the time. Mav hands her the best spoon.",8,J.Tow,J.Relieve,J.Guide),
            Landfall("wake-mast-dinner","Dinner at the East Side",
                "Mav’s dinner has been kept warm for twenty years in a family recipe. There is enough for every passenger if someone sets the long table across two moving boats.","Trestle Crab","The two bell ringers sit at opposite ends. Between them are more people than the old table ever held. Mav says it was worth keeping warm.",8,
                At(A.Brace,S.West,"Floating trestles","Brace the long table across both hulls"),
                At(A.Seat,S.East,"Door knockers","Seat the old knockers around the traveling mast"),
                At(A.Guide,S.Stairs,"Second ringer","Guide the bathhouse keeper to the east chair")))
    ];
}
